<h1>Pesanan Tiket</h1><form method="get" class="cari"><input type="hidden" name="r" value="ticket_orders"><select name="event_id"><option value="">Semua event</option><?php foreach($events as $id=>$label): ?><option value="<?= (int)$id ?>"<?= $id===$eventId?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><select name="status"><option value="">Semua status</option><?php foreach(ORDER_STATUSES as $s): ?><option value="<?= e($s) ?>"<?= $s===$status?' selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><button>Filter</button></form><div class="tabel-wrap"><table><thead><tr><th>Waktu</th><th>Event</th><th>Pemesan</th><th>Jumlah</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><?= e($order['created_at']) ?></td><td><?= e($order['event_title']) ?></td><td><?= e($order['full_name']) ?><br><small><?= e($order['email']) ?> · <?= e($order['phone']) ?></small><?php if($order['notes']): ?><br><?= e($order['notes']) ?><?php endif; ?></td><td><?= (int)$order['quantity'] ?></td><td><?= e(rupiah($order['total_price'])) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$order['id'] ?>"><select name="status"><?php foreach(ORDER_STATUSES as $s): ?><option value="<?= e($s) ?>"<?= $s===$order['status']?' selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><button>Simpan</button></form></td><td><?php if(admin_can($admin,['super_admin'])): ?><form method="post" onsubmit="return confirm('Hapus pesanan?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="do" value="delete"><button class="hapus">Hapus</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="7">Belum ada pesanan.</td></tr><?php endif; ?></tbody></table></div>
